$view=(string)($_GET['view']??'dashboard');$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&validate_csrf_or_abort(false)){
 try{$action=(string)($_POST['action']??'');if($action==='save_lead'){$id=$crm->saveLead($_POST);header('Location: crm.php?view=leads&created='.$id);exit;}if($action==='save_activity'){$crm->saveActivity($_POST);$notice='Atividade criada.';}if($action==='complete_activity'){$pdo->prepare('UPDATE crm_activities SET status="COMPLETED",completed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=? AND (assigned_to=? OR ?=1)')->execute([(int)$_POST['id'],(int)$user['id'],$crm->isAdmin()?1:0]);$notice='Atividade concluída.';}if($action==='move_opportunity'){$crm->moveOpportunity((int)$_POST['id'],(string)$_POST['stage']);if(($_SERVER['HTTP_ACCEPT']??'')==='application/json'){header('Content-Type: application/json');echo json_encode(['ok'=>true]);exit;}$notice='Pipeline atualizado.';}}
 catch(Throwable $e){$error=$e->getMessage();if(($_SERVER['HTTP_ACCEPT']??'')==='application/json'){http_response_code(422);header('Content-Type: application/json');echo json_encode(['ok'=>false,'error'=>$error]);exit;}}
}
$dashboard=$crm->dashboard();$leads=$crm->leads();$activities=$crm->activities();
$opportunities=$pdo->query('SELECT o.*,COALESCE(c.name,o.company) company_name,u.name assigned_name,(SELECT MIN(due_datetime) FROM crm_activities a WHERE a.related_type="opportunity" AND a.related_id=o.id AND a.status="PENDING") next_activity FROM crm_opportunities o LEFT JOIN erp_customers c ON c.id=o.customer_id LEFT JOIN users u ON u.id=o.assigned_to ORDER BY o.updated_at DESC')->fetchAll();
$customers=$pdo->query('SELECT c.*,COUNT(DISTINCT po.id) order_count,MAX(po.created_at) last_order,COALESCE(SUM(po.planned_quantity*COALESCE(fp.sale_price,0)),0) commercial_value FROM erp_customers c LEFT JOIN erp_production_orders po ON po.customer_id=c.id LEFT JOIN erp_finished_products fp ON fp.id=po.finished_product_id GROUP BY c.id ORDER BY c.name')->fetchAll();
$users=$pdo->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();
$pageTitle='CRM · '.(['dashboard'=>'Dashboard','day'=>'Meu Dia','leads'=>'Leads','pipeline'=>'Pipeline','customers'=>'Clientes 360º','contacts'=>'Contactos','projects'=>'Projetos','activities'=>'Atividades','agenda'=>'Agenda','tasks'=>'Tarefas','reports'=>'Relatórios','settings'=>'Configurações'][$view]??'Comercial');$bodyClass='bg-light crm-page';require __DIR__.'/partials/header.php';
$money=function($v){return number_format((float)$v,0,',','.').' €';};
