<section class="crm-kpis">
<?php foreach([
 ['Leads ativos',$d['leads']['active'],'bi-person-lines-fill','leads'],['Novos este mês',$d['leads']['new_month'],'bi-sparkles','leads&filter=new'],['Oportunidades abertas',$d['opportunities']['open_count'],'bi-bullseye','pipeline'],['Pipeline total',$money($d['opportunities']['pipeline']),'bi-bar-chart-steps','pipeline'],['Pipeline ponderado',$money($d['opportunities']['weighted']),'bi-graph-up-arrow','pipeline'],['Negócios ganhos',$d['opportunities']['won'],'bi-trophy','pipeline&filter=won'],['Negócios perdidos',$d['opportunities']['lost'],'bi-x-circle','pipeline&filter=lost'],['Taxa conversão',(($d['opportunities']['won']+$d['opportunities']['lost'])?number_format($d['opportunities']['won']*100/($d['opportunities']['won']+$d['opportunities']['lost']),1,',','.'):0).'%','bi-percent','reports'],['Tarefas pendentes',$d['activities']['pending'],'bi-check2-square','tasks'],['Atividades atrasadas',$d['activities']['overdue'],'bi-alarm','day'],['Clientes ativos',$d['customers'],'bi-buildings','customers'],['Leads esquecidos',$d['leads']['stale'],'bi-exclamation-triangle','leads&filter=stale']
 ] as $k):?><a class="crm-kpi" href="crm.php?view=<?=$k[3]?>"><i class="bi <?=$k[2]?>"></i><strong><?=$k[1]?></strong><b><?=h((string)$k[0])?></b><span>Explorar <i class="bi bi-arrow-right"></i></span></a><?php endforeach;?>
</section>
<div class="crm-grid"><section class="crm-panel"><header><div><small>AGENDA COMERCIAL</small><h3>O que precisa da sua atenção</h3></div><a href="crm.php?view=day">Ver Meu Dia</a></header><?php foreach(array_slice($activities,0,6) as $a):?><div class="crm-agenda-row <?=empty($a['completed_at'])&&$a['due_datetime']<date('Y-m-d H:i:s')?'is-overdue':''?>"><time><?=h($a['due_datetime']?date('H:i',strtotime($a['due_datetime'])):'—')?></time><i class="bi bi-<?=($a['type']==='CALL'?'telephone':($a['type']==='MEETING'?'people':'check2-circle'))?>"></i><div><strong><?=h($a['title'])?></strong><small><?=h($a['type'])?> · <?=h((string)$a['due_datetime'])?></small></div></div><?php endforeach;if(!$activities):?><div class="crm-empty">Sem atividades. Crie o primeiro contacto comercial.</div><?php endif;?></section><section class="crm-panel"><header><div><small>FORECAST</small><h3>Previsão ponderada</h3></div></header><div class="crm-forecast"><div><span>Este mês</span><b><?=$money($d['opportunities']['weighted'])?></b></div><div class="crm-donut" style="--value:<?=min(100,(int)($d['opportunities']['pipeline']?($d['opportunities']['weighted']/$d['opportunities']['pipeline']*100):0))?>"><span><?=($d['opportunities']['pipeline']?round($d['opportunities']['weighted']/$d['opportunities']['pipeline']*100):0)?>%</span></div></div><p class="text-muted small">Calculado de forma transparente: valor estimado × probabilidade.</p></section></div>
