<?php elseif($view==='pipeline'):?>
<div class="crm-kanban" data-crm-kanban><?php foreach(['NEW'=>'Novo','CONTACTED'=>'Contactado','QUALIFIED'=>'Qualificado','PROPOSAL'=>'Proposta','NEGOTIATION'=>'Negociação','WON'=>'Ganho','LOST'=>'Perdido'] as $stage=>$label):?><section class="crm-column" data-stage="<?=$stage?>"><header><span><?=$label?></span><b><?=count(array_filter($opportunities,function($o)use($stage){return $o['stage']===$stage;}))?></b></header><div class="crm-dropzone"><?php foreach($opportunities as $o):if($o['stage']!==$stage)continue;?><article class="crm-deal" draggable="true" data-id="<?=$o['id']?>"><small><?=h($o['company_name'])?></small><h4><?=h($o['title'])?></h4><strong><?=$money($o['estimated_value'])?></strong><div class="progress"><span style="width:<?=$o['probability']?>%"></span></div><footer><span><?=$o['probability']?>%</span><span><i class="bi bi-person"></i> <?=h($o['assigned_name'])?></span></footer></article><?php endforeach;?></div></section><?php endforeach;?></div>
